$pdf = @{
 'specs\US-01\spec.md' = 'Form configured by country','Field validation','Configuration change without deployment','Keep data when going back'
 'specs\US-02\spec.md' = 'Plans for the country','Recommended plan','Plan selection','No plans available'
 'specs\US-03\spec.md' = 'Complete summary','Terms by country','Successful payment','Rejected payment'
}
foreach ($f in $pdf.Keys | Sort-Object) {
  $t = Get-Content $f -Raw -Encoding UTF8
  $missing = $pdf[$f] | Where-Object { $t -notmatch [regex]::Escape("Scenario: $_") }
  $req = ([regex]::Matches($t, '(?m)^\| REQ-0\d\.\d+ ')).Count
  $ac = ([regex]::Matches($t, '(?m)^\| AC-0\d\.\d+ ')).Count
  $noVerif = ([regex]::Matches($t, '(?m)^\| REQ-0\d\.\d+ .*\|\s*\|\s*$')).Count
  "{0}: escenarios PDF ausentes=[{1}] · filas REQ={2} · filas AC={3} · REQ sin verificacion={4} · estado={5}" -f $f, ($missing -join ', '), $req, $ac, $noVerif, ([regex]::Match($t, '\| Estado \| ([^|]+)\|').Groups[1].Value.Trim())
}
"--- AC-02.8 ejemplos"; Select-String -Path specs\US-02\spec.md -Pattern '1\.320\.000|38\.985' | ForEach-Object { $_.LineNumber.ToString() + ': ' + $_.Line.Trim() }

