const pick=(el)=>{const c=getComputedStyle(el);return {tag:el.tagName,cls:(el.className&&el.className.toString().slice(0,40))||'',txt:(el.innerText||'').trim().slice(0,30),color:c.color,bg:c.backgroundColor,font:c.fontFamily.slice(0,60),size:c.fontSize,weight:c.fontWeight,radius:c.borderRadius,border:c.border.slice(0,40),pad:c.padding,shadow:c.boxShadow.slice(0,60)}};
const out={};
out.body=pick(document.body);
out.h=[...document.querySelectorAll('h1,h2,h3')].slice(0,6).map(pick);
out.btn=[...document.querySelectorAll('a[class*=btn],button,a[class*=button],[class*=cta]')].filter(e=>e.offsetParent).slice(0,8).map(pick);
const cols={};document.querySelectorAll('*').forEach(e=>{const c=getComputedStyle(e);[c.color,c.backgroundColor,c.borderTopColor].forEach(v=>{if(v&&v!=='rgba(0, 0, 0, 0)')cols[v]=(cols[v]||0)+1})});
out.colors=Object.entries(cols).sort((a,b)=>b[1]-a[1]).slice(0,25);
const fonts={};document.querySelectorAll('*').forEach(e=>{const f=getComputedStyle(e).fontFamily;fonts[f]=(fonts[f]||0)+1});out.fonts=Object.entries(fonts).sort((a,b)=>b[1]-a[1]).slice(0,5);
out.cards=[...document.querySelectorAll('[class*=card]')].filter(e=>e.offsetParent).slice(0,4).map(pick);
out.header=document.querySelector('header')?pick(document.querySelector('header')):null;
out.footer=document.querySelector('footer')?pick(document.querySelector('footer')):null;
JSON.stringify(out)

