SP="C:/Users/JORGEA~1/AppData/Local/Temp/claude/7c00b3cd46447d40/e47a27f0-74c7-4957-994a-94c086d65178/scratchpad"; mkdir -p "$SP/logo"; cp "C:/Users/JORGEA~1/AppData/Local/Temp/claude/d13de0a0717ac5de/e47a27f0-74c7-4957-994a-94c086d65178/images/1.webp" "$SP/logo/src.webp"; cat > "$SP/logo/make.cjs" <<'EOF'
const path = require('path');
const { chromium } = require(process.argv[2]);
(async () => {
  const dir = process.argv[3];
  const b64 = require('fs').readFileSync(path.join(dir, 'src.webp')).toString('base64');
  const browser = await chromium.launch({ channel: 'chrome' });
  const page = await browser.newPage();
  const out = await page.evaluate(async (b64) => {
    const img = new Image(); img.src = 'data:image/webp;base64,' + b64; await img.decode();
    const c = document.createElement('canvas'); c.width = img.width; c.height = img.height;
    const x = c.getContext('2d'); x.drawImage(img, 0, 0);
    const d = x.getImageData(0, 0, c.width, c.height); const p = d.data;
    let minX = c.width, minY = c.height, maxX = 0, maxY = 0, hadAlpha = false;
    for (let i = 0; i < p.length; i += 4) {
      if (p[i+3] < 255) hadAlpha = true;
      const lum = (p[i] + p[i+1] + p[i+2]) / 3;
      // ink = how far from white; recolour to white, keep ink as alpha
      const ink = Math.max(0, Math.min(255, (255 - lum) * 255 / (255 - 60)));
      const a = Math.round(ink * p[i+3] / 255);
      p[i] = p[i+1] = p[i+2] = 255; p[i+3] = a;
      if (a > 20) { const px = (i/4) % c.width, py = Math.floor(i/4 / c.width);
        minX = Math.min(minX, px); maxX = Math.max(maxX, px); minY = Math.min(minY, py); maxY = Math.max(maxY, py); }
    }
    x.putImageData(d, 0, 0);
    const pad = 4, w = maxX - minX + 1 + 2*pad, h = maxY - minY + 1 + 2*pad;
    const c2 = document.createElement('canvas'); c2.width = w; c2.height = h;
    c2.getContext('2d').drawImage(c, minX - pad, minY - pad, w, h, 0, 0, w, h);
    return { url: c2.toDataURL('image/png'), w, h, src: [img.width, img.height], hadAlpha };
  }, b64);
  require('fs').writeFileSync(path.join(dir, 'sura-logo-white.png'), Buffer.from(out.url.split(',')[1], 'base64'));
  console.log(JSON.stringify({ w: out.w, h: out.h, src: out.src, hadAlpha: out.hadAlpha }));
  await browser.close();
})();
