import re, sys, zlib

data = open(sys.argv[1], 'rb').read()

# Map object number -> decompressed stream.
objs = {}
for m in re.finditer(rb'(\d+)\s+0\s+obj(.*?)endobj', data, re.S):
    body = m.group(2)
    sm = re.search(rb'stream\r?\n(.*?)\r?\nendstream', body, re.S)
    if sm:
        try:
            objs[int(m.group(1))] = zlib.decompress(sm.group(1))
        except Exception:
            pass

# Merge every ToUnicode CMap (fonts with 2-byte CIDs usually share glyph ids per font; good enough to search).
cmaps = []
for num, s in objs.items():
    if b'beginbfchar' in s or b'beginbfrange' in s:
        cm = {}
        for block in re.findall(rb'beginbfchar(.*?)endbfchar', s, re.S):
            for a, b in re.findall(rb'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', block):
                cm[int(a, 16)] = bytes.fromhex(b.decode()).decode('utf-16-be', 'replace')
        for block in re.findall(rb'beginbfrange(.*?)endbfrange', s, re.S):
            for a, b, c in re.findall(rb'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', block):
                start, end, dst = int(a, 16), int(b, 16), int(c, 16)
                for i in range(end - start + 1):
                    cm[start + i] = chr(dst + i)
        cmaps.append(cm)

out = []
for num, s in sorted(objs.items()):
    if b'TJ' not in s and b'Tj' not in s:
        continue
    for line in re.findall(rb'\[(.*?)\]\s*TJ|<([0-9A-Fa-f]+)>\s*Tj', s, re.S):
        chunk = line[0] or (b'<' + line[1] + b'>')
        for h in re.findall(rb'<([0-9A-Fa-f]+)>', chunk):
            codes = [int(h[i:i + 4], 16) for i in range(0, len(h), 4)]
            best = max(cmaps, key=lambda cm: sum(1 for c in codes if c in cm)) if cmaps else {}
            out.append(''.join(best.get(c, '?') for c in codes))
        out.append(' ')
    out.append('\n')
text = ''.join(out)
open(sys.argv[2], 'w', encoding='utf-8').write(text)
print(len(cmaps), 'cmaps', len(text), 'chars')

