// Throwaway: README screenshots against the compose stack (not part of the repo).
// argv: <playwright path> <out dir>
const { chromium } = require(process.argv[2]);
const out = process.argv[3];
const base = 'http://localhost:8080';

async function fillCo(page) {
  await page.getByLabel('Tipo de documento').selectOption({ label: 'Cédula de ciudadanía' });
  await page.getByLabel('Número de documento').fill('1234567890');
  await page.getByLabel('Fecha de nacimiento').fill('2000-05-10');
  await page.getByLabel('Ciudad').selectOption({ label: 'Bogotá' });
  await page.getByLabel(/Autorizo el tratamiento/).check();
  await page.getByLabel('Placa').fill('ABC123');
  await page.getByLabel('Marca').selectOption({ label: 'Marca A' });
  await page.getByLabel('Año del vehículo').fill('2018');
}

(async () => {
  const browser = await chromium.launch({ channel: 'chrome' });
  const shot = async (page, name) => {
    await page.waitForTimeout(400);
    await page.mouse.move(0, 0);
    await page.screenshot({ path: `${out}/${name}.png` });
    console.log('saved', name);
  };

  // Desktop flow.
  const desk = await browser.newContext({ viewport: { width: 1280, height: 860 }, reducedMotion: 'reduce' });
  let page = await desk.newPage();
  await page.goto(base + '/');
  await page.getByRole('link', { name: 'Colombia' }).waitFor();
  await shot(page, '01-countries-1280');
  await page.getByRole('link', { name: 'Colombia' }).click();
  await page.getByLabel('Placa').waitFor();
  await fillCo(page);
  await page.evaluate(() => window.scrollTo(0, 0));
  await page.locator('body').click({ position: { x: 5, y: 400 } });
  await shot(page, '03-form-1280');
  await page.getByRole('button', { name: 'Continuar' }).click();
  await page.getByRole('radio', { name: /Plan Plus/ }).waitFor();
  await page.getByRole('radio', { name: /Plan Plus/ }).check();
  await shot(page, '04b-plans-selected-1280');
  await page.getByRole('button', { name: 'Continuar' }).click();
  await page.getByRole('checkbox', { name: /Acepto los términos/ }).check();
  await page.getByRole('button', { name: 'Pagar' }).click();
  await page.getByText(/CO-\d{8}-/).waitFor({ timeout: 15000 });
  await shot(page, '06-confirmation-1280');

  // Mobile summary (full page).
  const mob = await browser.newContext({ viewport: { width: 375, height: 812 }, reducedMotion: 'reduce', isMobile: true, hasTouch: true });
  page = await mob.newPage();
  await page.goto(base + '/co/form');
  await page.getByLabel('Placa').waitFor();
  await fillCo(page);
  await page.getByRole('button', { name: 'Continuar' }).click();
  await page.getByRole('radio', { name: /Plan Plus/ }).check();
  await page.getByRole('button', { name: 'Continuar' }).click();
  await page.getByRole('checkbox', { name: /Acepto los términos/ }).waitFor();
  await page.waitForTimeout(400);
  await page.screenshot({ path: `${out}/05-summary-375.png`, fullPage: true });
  console.log('saved 05-summary-375');
  await page.goto(base + '/');
  await page.getByRole('link', { name: 'Colombia' }).waitFor();
  await shot(page, '01-countries-375');

  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

